SELECT COALESCE(w.entry_stage,'NO_MATCH') AS entry_stage, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_gross, ROUND(SUM(p.realized_pnl - 0.001*p.quantity*(p.entry_price+p.exit_price)),6) AS pnl_net_est FROM paper_position p LEFT JOIN wallet_managed_position w ON w.entry_signal_id = p.signal_id WHERE p.status='CLOSED' AND p.closed_at >= '2026-10-03 00:00:00' AND p.exit_price IS NOT NULL GROUP BY COALESCE(w.entry_stage,'NO_MATCH') ORDER BY n DESC LIMIT 50;